const { readFileSync } = await import("fs");
const { execFileSync } = await import("child_process");
const activity = $root + "/docs/story/activity.jsonl";
const count = () => readFileSync(activity, "utf8").split("\n").filter(Boolean).length;
const before = count();
execFileSync(process.execPath, ["packages/main/dist/cli.js", "session_brief", "--concise"], { cwd: $root, encoding: "utf8" });
execFileSync(process.execPath, ["packages/main/dist/cli.js", "status", "--concise"], { cwd: $root, encoding: "utf8" });
execFileSync(process.execPath, ["packages/main/dist/cli.js", "next"], { cwd: $root, encoding: "utf8" });
const after = count();
return { before, after, stable: before === after };

const { appendFileSync } = await import("fs");
const { execFileSync } = await import("child_process");
appendFileSync($root + "/docs/story/activity.jsonl", JSON.stringify({ tool: "fixture-noise", status: "ok" }) + "\n");
const out = execFileSync(process.execPath, ["packages/main/dist/cli.js", "session_brief", "--concise"], { cwd: $root, encoding: "utf8" });
return { hidesActivityPath: !out.includes("docs/story/activity.jsonl"), hasBrief: out.includes("# koala session brief") };

const { readFileSync } = await import("fs");
const { execFileSync } = await import("child_process");
const activity = $root + "/docs/story/activity.jsonl";
const count = () => readFileSync(activity, "utf8").split("\n").filter(Boolean).length;
const before = count();
execFileSync(process.execPath, ["packages/main/dist/cli.js", "checklist_update", JSON.stringify({ storyId: "B-d139", itemId: "CHK-003", status: "done" })], { cwd: $root, encoding: "utf8" });
const after = count();
return { before, after, appended: after > before };

const name = "residue-fixture-" + Date.now();
const created = await $handlers.story_create({ name, title: "Residue fixture", description: "Synthetic discarded residue", type: "bug", priority: "low", forceNew: true });
const storyId = created.match(/B-[a-f0-9]+/)[0];
await $handlers.story_discard({ storyId, confirm: true, reason: "fixture setup" });
const preview = await $handlers.story_discard({ storyId, cleanupResidue: true, dryRun: true });
return { preview, hasRemovePlan: preview.includes("remove untracked discarded story residue") };

const out = await $handlers.aux_doc_list({ format: "json" });
const parsed = JSON.parse(out);
return { hasDocs: parsed.count > 0, hasAgents: parsed.docs.some((d) => d.path === "AGENTS.md") };

const { execFileSync } = await import("child_process");
const out = execFileSync(process.execPath, ["bin/koala.js", "aux_doc_list", "--format=json"], { cwd: $root, encoding: "utf8" });
return { ok: out.includes("\"count\"") && !out.includes("Handler already registered") };

const out = await $handlers.aux_doc_list({ format: "json" });
const parsed = JSON.parse(out);
return { skipsStory: !parsed.docs.some((d) => d.path.startsWith("docs/story/")), skipsFixtures: !parsed.docs.some((d) => d.path.includes("tests/fixtures")) };
